package cultural

import (
    "time"
)

type Artifact struct {
    ID           string
    Name         string
    Dynasty      string
    Category     string
    MuseumID     string
    Model3DRef   string
    ImageRefs    []string
    Description  string
    CreatedAt    time.Time
    BlockchainTx string
}

type ArtifactService struct {
    artifacts map[string]*Artifact
}

func (s *ArtifactService) Register(a *Artifact) error {
    s.artifacts[a.ID] = a
    return nil
}
